def residual_scale(c):
    from scipy.linalg import eigh
    (d, u) = eigh(c, check_finite=False)
    w = u[:, :-2] ** 2
    return np.sqrt(w @ (1 / d[:-2]) / w.sum(axis=1))

def generate(seed, mode, n=900):
    rng = np.random.default_rng(seed)
    p = 24
    ix = rng.permutation(p)
    A = np.zeros((p, p), bool)

    def put(i, j):
        A[i, j] = A[j, i] = True
    if mode in ('ring', 'sign', 'weak', 'coherent', 'hetero', 'weaker_factors'):
        for i in range(p):
            put(ix[i], ix[(i + 1) % p])
        for (i, j) in rng.choice(p, size=(4, 2), replace=False):
            put(ix[i], ix[j])
    else:
        while A.sum() < 2 * (23 + seed % 10):
            (i, j) = rng.choice(p, 2, replace=False)
            if A.sum(0)[[i, j]].max() < (5 if mode == 'hubs' else 4):
                put(i, j)
    S = 2.2 * np.eye(p)
    (i, j) = np.where(np.triu(A, 1))
    weights = np.full(len(i), 0.52)
    if mode in ('weak', 'hubs'):
        weights = rng.uniform(0.34, 0.59, len(i))
    if mode != 'ring':
        weights *= rng.choice([-1.0, 1.0], len(i))
    S[i, j] = S[j, i] = -weights
    if mode == 'hetero':
        sc = np.exp(rng.uniform(-0.55, 0.55, p))
        S *= np.outer(sc, sc)
    B = rng.normal(size=(p, 2)) * 0.9
    if mode == 'coherent':
        B[:5] *= 3
    if mode == 'weaker_factors':
        B *= 0.4
    X = rng.standard_normal((n, p)) @ np.linalg.cholesky(np.linalg.inv(S)).T + rng.standard_normal((n, 2)) @ B.T
    return (X, A, S)

def case(seed, mode):
    if mode != 'hetero_coherent':
        return generate(seed, mode)[:2]
    (_, y, t) = generate(seed, 'hetero')
    rng = np.random.default_rng(seed + 800)
    b = rng.normal(size=(24, 2)) * 0.9
    b[:5] *= 2.5
    x = rng.normal(size=(900, 24)) @ np.linalg.cholesky(np.linalg.inv(t)).T + rng.normal(size=(900, 2)) @ b.T
    return (x, y)

